'use strict';
/* Rotina diária e adaptações de uso da Nova Aliança. */
const exp={today:null,todayError:'',history:null,lists:[],search:'',onlyUnmarked:false,lastMark:'',events:null,form:null,queueBusy:false,lastInteraction:Date.now(),pollFailures:0};
const expButton=(action,label,extra='',primary=false)=>`<button type="button" data-exp-action="${action}" ${extra} class="${primary?'primary':''}">${esc(label)}</button>`;
function expUserKey(prefix){return prefix+'-'+novaCurrentUser().id}
function expRead(key,fallback=null){try{return JSON.parse(sessionStorage.getItem(key))??fallback}catch{return fallback}}
function expWrite(key,value){try{sessionStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
const originalExperienceReset=novaClearFleet;novaClearFleet=function(){originalExperienceReset();exp.today=null;exp.todayError='';exp.history=null;exp.historyFilters={};exp.historySequence=(exp.historySequence||0)+1;exp.lists=[];exp.search='';exp.onlyUnmarked=false;exp.lastMark='';exp.events=null;exp.form=null;exp.queueBusy=false};
novaNavigation=function(){const user=novaCurrentUser();if(user?.role==='employee')return [['today','Hoje','grid'],['school','Chamadas','bus'],['point','Meu ponto','clock']];return [['today','Hoje','grid'],['fleet','Frota','bus'],['school','Chamadas','user'],['point','Meu ponto','clock'],...(user?.role==='admin'?[['employees','Equipe','user']]:[]),['alerts','Alertas','bell'],['fuel','Abastecimentos','fuel'],['reports','Resumo','chart'],['settings','Ajustes','settings']]};
const originalExperienceGo=novaGo;novaGo=async function(target){if(target==='today'){if(pendingChanges)throw Error('Salve as alterações pendentes antes de trocar de área.');closeModal();selected=null;page='today';shell();return loadExperienceToday()}return originalExperienceGo(target)};
async function loadExperienceToday(){const token=novaCaptureSession();try{const data=await requestShared('/api/today');if(!novaSessionCurrent(token))return;exp.today=data;exp.todayError='';exp.pollFailures=0;if(page==='today'&&!document.getElementById('modal').open)shell()}catch(e){if(e.staleSession)return;exp.todayError=e.message;exp.pollFailures++;if(page==='today')shell()}}
function experienceTodayView(){const data=exp.today,user=novaCurrentUser(),alerts=allAlerts(),urgent=alerts.filter(a=>a.level==='red'),soon=alerts.filter(a=>a.level==='yellow'),pending=alerts.filter(a=>a.level==='pending'),routes=data?.routes||[],closed=routes.filter(r=>r.status==='done').length;return `${pageHead('Hoje','Olá, '+esc(user.name.split(' ')[0])+'. Veja os próximos compromissos.',expButton('today-refresh','Atualizar'))}${exp.todayError?`<div class="rule-note" role="status">${esc(exp.todayError)} ${data?'Os últimos dados confirmados continuam visíveis.':''}</div>`:''}${!data?'<section class="panel"><p role="status">Carregando a rotina do dia…</p></section>':`<div class="today-strip"><div><strong>${closed}/${routes.length}</strong><span>viagens concluídas</span></div><div><strong>${data.point.summary.status==='working'?'Aberta':data.point.summary.status==='break'?'Intervalo':data.point.summary.original.length?'Encerrada':'Sem registro'}</strong><span>minha jornada</span></div>${user.role!=='employee'?`<div><strong>${urgent.length}</strong><span>avisos urgentes</span></div>`:''}</div><div class="today-columns"><section class="panel"><div class="section-head"><h2>Viagens de hoje</h2>${novaButton('go-school','Ver chamadas')}</div>${routes.filter(r=>r.status!=='done').sort((a,b)=>a.time.localeCompare(b.time)).map(r=>`<article class="today-trip"><div><span class="today-time">${esc(r.time)}</span><small>${esc(r.direction)}</small></div><div><strong>${esc(r.school)}</strong><p>${esc(r.line)} · ${r.students} aluno(s)</p>${badge(r.status==='progress'?'yellow':'pending',r.status==='progress'?'Em andamento':'Aguardando')}</div>${expButton('today-trip',r.status==='progress'?'Continuar':'Iniciar',`data-route="${esc(r.id)}"`)}</article>`).join('')||'<div class="calm-empty">'+icon('check')+'<p>'+(!routes.length?'Nenhuma viagem prevista para hoje.':'Todas as viagens de hoje foram concluídas.')+'</p></div>'}</section><section class="panel"><div class="section-head"><h2>Meu ponto</h2>${novaButton('go-point','Abrir meu ponto')}</div><p class="help">${esc(user.name)} · ${esc(novaScheduleText(data.point.summary.planned))}</p><p class="today-point-state">${{working:'Jornada em andamento',break:'Em intervalo',outside:'Sem jornada aberta'}[data.point.summary.status]}</p><p>${data.point.summary.original.length} marcação(ões) nesta jornada</p><p class="help">O horário de cada registro é confirmado pelo servidor.</p></section></div>`}${user.role!=='employee'?`<section class="panel"><div class="section-head"><h2>Prioridades da frota</h2>${btn('nav','Ver todos os avisos','','','alerts')}</div><div class="priority-counts"><span class="tag red">${urgent.length} urgentes</span><span class="tag yellow">${soon.length} próximos do prazo</span><span class="tag pending">${pending.length} dados a conferir</span></div>${alertRows([...urgent,...soon].slice(0,6))||'<p class="help">Nenhum prazo ou problema urgente nos registros atuais. Os dados a conferir estão separados nos alertas.</p>'}</section>`:''}${data?.team?`<section class="panel"><div class="section-head"><h2>Jornadas para acompanhar</h2>${novaButton('go-employees','Ver equipe')}</div>${data.team.filter(u=>u.review).map(u=>`<div class="row"><div class="grow"><strong>${esc(u.name)}</strong><p>${u.status==='outside'?'Marcações para conferir':'Jornada em aberto'}</p></div>${novaButton('employee-report','Conferir',`data-employee="${esc(u.id)}"`)}</div>`).join('')||'<p class="help">Nenhuma inconsistência ou jornada aberta nos registros consultados.</p>'}<p class="help">Situações indicativas para conferência, sem cálculo de folha ou conclusão automática de falta.</p></section>`:''}`}
const originalExperienceShell=shell;shell=function(){originalExperienceShell();if(novaAuth.stage!=='ready')return;document.body.dataset.page=page;const nav=novaNavigation(),primary=novaCurrentUser().role==='employee'?nav:nav.filter(([p])=>['today','fleet','school'].includes(p));document.querySelector('.main')?.insertAdjacentHTML('beforeend',`<nav class="mobile-nav" aria-label="Navegação no celular">${primary.map(([p,l,i])=>`<button data-exp-action="nav" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}${novaCurrentUser().role!=='employee'?`<button data-exp-action="more" ${!['today','fleet','school'].includes(page)?'aria-current="page"':''}>${icon('settings')}<span>Mais</span></button>`:''}</nav>`);if(page==='today'){const content=document.querySelector('.content');content.innerHTML=sharedNotice()+experienceTodayView()+'<div class="footer-note">Nova Aliança Transportes · Mogi das Cruzes, SP</div>';const crumb=document.querySelector('.crumb strong');if(crumb)crumb.textContent='Hoje'}if(page!=='school'&&expQueue().length)document.querySelector('.content')?.insertAdjacentHTML('afterbegin',`<div class="queue-banner" role="status"><strong>${expQueue().length} marcação(ões) de chamada pendente(s) nesta aba.</strong><p>Ainda não confirmadas no servidor.</p>${expButton('nav','Ver chamadas',"data-page='school'")}${expButton('queue-flush','Sincronizar agora')}</div>`);if(page==='point'||page==='employees'){document.querySelectorAll('.nova-table-scroll').forEach(node=>node.classList.add('journey-desktop'))}if(page==='school'&&naSchool.trip)expWireCall();document.getElementById('school-history-range')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);expLoadHistory(Object.fromEntries(f)).catch(e=>toast(e.message))})};
function experienceMore(){profileDialog('Mais opções',novaCurrentUser().name,`<div class="more-menu">${novaNavigation().filter(([p])=>!['today','fleet','school'].includes(p)).map(([p,l,i])=>`<button data-exp-action="nav" data-page="${p}" ${page===p?'aria-current="page"':''}>${icon(i)}${esc(l)}${icon('arrow')}</button>`).join('')}</div>`,novaButton('account','Minha conta'))}
// A cor operacional não depende de completar o cadastro.
fleetView=function(){const counts={all:state.vehicles.length,red:0,yellow:0,pending:0,green:0};state.vehicles.forEach(v=>counts[vehicleStatus(v)]++);return `${pageHead('Frota','Encontre o veículo pela placa.',btn('fuel-add','Abastecer','fuel')+btn('vehicle-add','Novo veículo','plus','primary'))}<div class="fleet-search-tools tools company-tools">${companyOptions()}<label class="search">${icon('search')}<input id="search" value="${esc(query)}" placeholder="Placa, modelo ou motorista" aria-label="Buscar veículo"></label>${operationalFilterControl()}</div><div class="fleet-situation-filters filters" aria-label="Filtrar por situação">${[['all','Todos'],['red','Urgentes'],['yellow','Prazo próximo'],['pending','Cadastro a conferir'],['green','Em dia']].map(([key,label])=>btn('filter',`${label} <span>${counts[key]}</span>`,'',filter===key?'active':'',key,`aria-pressed="${filter===key}"`)).join('')}</div><p class="help">${state.vehicles.length} veículo(s) · Documentos e manutenção são acompanhados separadamente dos dados que ainda faltam.</p><div class="fleet-grid" id="vehicle-grid">${vehicleCards()}</div>`};
const originalExperienceAlerts=alertsView;alertsView=function(){return originalExperienceAlerts().replace('O que precisa de cuidado, por ordem de prioridade.','Prazos e problemas operacionais separados dos dados a conferir.').replace("alertFilter==='all'||a.level===alertFilter", "alertFilter==='all'||a.level===alertFilter")};
// Relatórios de jornada em dias expansíveis no celular.
const originalExperienceReport=novaReportView;novaReportView=function(report,admin){const desktop=originalExperienceReport(report,admin);return `<div class="journey-desktop">${desktop}</div><div class="journey-mobile"><div class="nova-report-summary"><strong>${novaHours(report.totalWorkedMinutes)} de períodos encerrados</strong><p>${report.completeDays} dia(s) com jornada fechada · ${report.reviewDays} para conferir</p>${novaButton(admin?'admin-csv':'own-csv','Exportar CSV',admin?`data-employee="${esc(report.employee.id)}"`:'')}</div>${report.days.map(d=>`<details class="journey-day"><summary><span><strong>${fmt(d.date)}</strong><small>${d.anomalies.length?'Conferir marcações':d.effective.length?d.complete?'Jornada fechada':'Em aberto':'Sem marcações'}</small></span><b>${d.effective.length?novaHours(d.workedMinutes):'—'}</b></summary><p class="help">Previsto: ${esc(novaScheduleText(d.planned))}</p>${d.original.map(p=>`<div class="journey-entry"><span>${esc(novaKinds[p.kind])}<small>${novaClock(p.at)}</small></span>${admin?novaButton('ignore-punch','Desconsiderar',`data-employee="${esc(report.employee.id)}" data-punch="${esc(p.id)}" data-day="${d.date}"`):''}</div>`).join('')||'<p class="help">Nenhuma marcação.</p>'}${d.anomalies.map(a=>`<p class="rule-note">${esc(a)}</p>`).join('')}${d.adjustments.map(a=>`<p class="help">Ajuste: ${esc(a.action==='include'?'Inclusão de '+novaKinds[a.kind]:'Registro desconsiderado')} · ${esc(a.reason)} · ${esc(a.actor||'Administrador')}</p>`).join('')}${d.balanceMinutes!==null?`<p>Diferença indicativa: ${novaHours(d.balanceMinutes)}</p>`:''}${admin?novaButton('add-adjustment','Registrar ajuste',`data-employee="${esc(report.employee.id)}" data-day="${d.date}"`):''}</details>`).join('')}</div>`};
// Aviso curto sem cobrir os campos; erros continuam dentro do formulário.
toast=function(message){const node=document.getElementById('toast');node.innerHTML=`<span>${esc(message)}</span><button type="button" data-exp-action="dismiss-toast" aria-label="Fechar aviso">×</button>`;node.style.display='flex';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>node.style.display='none',6500)};
// Rascunhos de formulário: somente nesta aba e nesta conta, sem campos de senha.
const originalExperienceModal=modal;modal=function(title,sub,body,onSubmit,submit){let formKey,eligible=false,submitted=false;const token=novaCaptureSession();originalExperienceModal(title,sub,body,async(f,form)=>{await onSubmit(f,form);submitted=true;if(formKey)sessionStorage.removeItem(formKey);if(exp.form?.form===form)exp.form=null},submit);const form=document.getElementById('modal-form');if(!form)return;eligible=!!novaCurrentUser()&&!form.querySelector('input[type="password"],input[type="file"]')&&!/FIPE|recupera|retifica|Substituir|Arquivar/i.test(title);if(!eligible){exp.form=null;return}formKey=expUserKey('nova-form-'+title+'-'+sub);const fields=()=>Array.from(form.elements).filter(e=>e.name&&!['password','file','submit','button'].includes(e.type));const serialize=()=>fields().map(e=>({name:e.name,value:e.value,checked:['checkbox','radio'].includes(e.type)?e.checked:undefined}));let restored=expRead(formKey);if(restored&&restored.at<=Date.now()-86400000){sessionStorage.removeItem(formKey);restored=null}if(restored){const indexed=new Map();for(const e of fields()){const n=indexed.get(e.name)||0,item=restored.values.filter(v=>v.name===e.name)[n];indexed.set(e.name,n+1);if(item){if(['checkbox','radio'].includes(e.type))e.checked=!!item.checked;else if(e.tagName!=='SELECT'||Array.from(e.options).some(o=>o.value===item.value))e.value=item.value}}}const initial=JSON.stringify(serialize()),record={form,key:formKey,dirty:!!restored,token,submitted:()=>submitted};exp.form=record;form.querySelector('.modal-body').insertAdjacentHTML('afterbegin',`<p class="help full form-draft-note" role="status">${restored?'Rascunho recuperado. ':'Ao preencher, '}seu rascunho fica guardado nesta aba por até 24 horas, somente para sua conta.</p>`);const save=()=>{record.dirty=JSON.stringify(serialize())!==initial||!!restored;if(record.dirty&&!expWrite(formKey,{at:Date.now(),values:serialize()})){form.querySelector('.form-draft-note').textContent='Não foi possível guardar o rascunho. Mantenha esta tela aberta até salvar.'}};form.addEventListener('input',save);form.addEventListener('change',save)};
function expConfirmClose(){const record=exp.form;if(!record?.form.isConnected||!record.dirty||record.submitted())return false;if(record.form.dataset.submitting==='1'){toast('Aguarde a confirmação do envio.');return true}if(!record.form.querySelector('.draft-confirm'))record.form.querySelector('.modal-body').insertAdjacentHTML('beforeend',`<div class="draft-confirm full" role="group" aria-label="Sair do formulário"><strong>Você ainda não salvou estas informações.</strong><p>Guarde o rascunho nesta aba ou continue preenchendo.</p><div class="actions">${expButton('draft-keep','Fechar e guardar')}${expButton('draft-continue','Continuar preenchendo','',true)}${expButton('draft-discard','Descartar rascunho')}</div></div>`);record.form.querySelector('.draft-confirm').scrollIntoView({block:'nearest'});return true}
document.getElementById('modal').addEventListener('cancel',e=>{if(expConfirmClose())e.preventDefault()});
// Atualização adaptativa: atividade, visibilidade, falhas e navegação definem a frequência.
function expPollDelay(){return Math.min(180000,(Date.now()-exp.lastInteraction>120000?90000:30000)*2**Math.min(exp.pollFailures,2))}
startSharedUpdates=function(){if(sharedUpdatesStarted)return;sharedUpdatesStarted=true;let timer;const tick=async()=>{if(document.visibilityState==='visible'&&novaAuth.stage==='ready'){try{if(page==='today')await loadExperienceToday();else if(['fleet','alerts','fuel','reports'].includes(page)||selected){await pullShared();if(sharedStatus==='offline')exp.pollFailures++;else exp.pollFailures=0}if(expQueue().length)await expFlushQueue()}catch{} }timer=setTimeout(tick,expPollDelay())};timer=setTimeout(tick,expPollDelay());for(const event of ['pointerdown','keydown'])document.addEventListener(event,()=>{exp.lastInteraction=Date.now()},{passive:true});document.addEventListener('visibilitychange',()=>{clearTimeout(timer);timer=setTimeout(tick,document.visibilityState==='visible'?500:expPollDelay())});window.addEventListener('online',()=>{clearTimeout(timer);timer=setTimeout(tick,500);expFlushQueue().catch(()=>{})});document.addEventListener('input',e=>{if(e.target.closest?.('#equipment-form'))equipmentDirty=true});document.addEventListener('change',e=>{if(e.target.closest?.('#equipment-form'))equipmentDirty=true})};
document.addEventListener('click',e=>{const close=e.target.closest('[data-action="close"]'),dialog=document.getElementById('modal');if(close||(e.target===dialog&&(()=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom})())){if(expConfirmClose()){e.preventDefault();e.stopImmediatePropagation();return}}const button=e.target.closest('[data-exp-action]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();Promise.resolve(experienceAction(button)).catch(error=>{if(!error.staleSession)toast(error.message)})},true);
async function experienceAction(button){switch(button.dataset.expAction){case'nav':return novaGo(button.dataset.page);case'more':return experienceMore();case'dismiss-toast':document.getElementById('toast').style.display='none';return;case'today-refresh':return loadExperienceToday();case'today-trip':await novaGo('school');return schoolAction({dataset:{schoolAction:'open',route:button.dataset.route}});case'draft-keep':exp.form=null;closeModal();return toast('Rascunho guardado nesta aba.');case'draft-continue':return exp.form?.form.querySelector('.draft-confirm')?.remove();case'draft-discard':sessionStorage.removeItem(exp.form.key);exp.form=null;closeModal();return;default:return experienceSchoolAction(button)}}

const baseExperienceSchoolRender=schoolRender;schoolRender=function(){const active=document.activeElement,student=active?.dataset?.student,value=active?.dataset?.value,scroll=window.scrollY;baseExperienceSchoolRender();if(page==='school'&&naSchool.trip){window.scrollTo(0,scroll);if(student&&value)document.querySelector('[data-student="'+CSS.escape(student)+'"][data-value="'+CSS.escape(value)+'"]')?.focus({preventScroll:true})}};
